 const body=`${locked?`<p class="notice">${txt('maintenanceLocked')}</p>`:''}<p>${esc(e?.equipment_code+' · '+nameOf(e))} · ${esc(r.form_name)}</p><div class="filter-row"><label>${txt('year')}<input id="recordYear" class="select" type="number" min="2000" max="2100" value="${r.year}"></label><label>${txt(oil?'oilReplacer':'performerName')}<input id="maintenanceName" class="select" maxlength="100" value="${esc(r.performer_name)}"></label></div>`+legend('maintenance',form||r)+`<div class="maintenance-rows">${r.rows.map((row,n)=>`<article class="maintenance-item"><h3>${n+1}. ${esc(multilingual(row.item.name))} <span class="maintenance-symbol">${symbols[row.cycle_code][r.status==='confirmed'&&row.completed_date?1:0]}</span></h3>${pmHasText(row.item.standard)?`<p>${txt('standard')}: ${esc(multilingual(row.item.standard))}</p>`:''}${pmHasText(row.item.method)?`<p>${txt('method')}: ${esc(multilingual(row.item.method))}</p>`:''}<div class="editor-fields"><label>${txt('cycleCode')}<select class="select" data-row="${n}" data-field="cycle_code">${Object.keys(symbols).map(c=>`<option value="${c}" ${c===row.cycle_code?'selected':''}>${txt('cycle'+c)}</option>`).join('')}</select></label><label>${txt('cycle')}<input class="select" data-row="${n}" data-field="cycle_text" value="${esc(row.cycle_text)}" maxlength="500"></label><label>${txt('plannedMonth')}<input class="select" type="month" data-month="${n}" value="${esc(row.planned_start.slice(0,7))}"></label>${[['plannedStart','planned_start'],['plannedEnd','planned_end'],['completedDate','completed_date']].map(([label,field])=>`<label>${txt(label)}<input class="select" type="date" data-row="${n}" data-field="${field}" ${field==='completed_date'?`max="${inspectionDay()}"`:''} value="${esc(row[field])}"></label>`).join('')}<label>${txt(oil?'oilNotes':'reason')}<input class="select" data-row="${n}" data-field="note" value="${esc(row.note)}" maxlength="2000"></label></div>${!locked?button('delete',`data-remove-maintenance="${n}"`,'danger'):''}</article>`).join('')}</div>${!locked?`<div class="filter-row"><select id="addMaintenanceItem" class="select">${(form?.items||[]).map((i,n)=>`<option value="${n}">${n+1}. ${esc(multilingual(i.name))}</option>`).join('')}</select>${button('addScheduleRow','id="addMaintenanceRow"')}</div>`:''}`;
 const modal=dialog('maintenanceEditor',window.inspectionFormTitle(form||r),body,locked?button('close','id="closeMaintenance"'):button('saveDraft','id="saveMaintenanceDraft"')+button(oil?'oilConfirm':'confirmMaintenance','id="confirmMaintenance"','primary'));
 modal.classList.add('maintenance-editor');if(locked){modal.querySelectorAll('.dialog-body input,.dialog-body select').forEach(x=>x.disabled=true);$('#closeMaintenance').onclick=()=>{maintenanceSession=null;modal.remove();};return;}
